"""Install the separate V3.2 audit update; preserve active reader/import code."""
from pathlib import Path
from datetime import datetime
import ast, base64, hashlib, json, os, shutil, zlib

DATA = ''


def main():
    root = Path(__file__).resolve().parent
    package = root/'Automation' if (root/'Automation/Common_Rules').is_dir() else root
    if not (package/'Common_Rules').is_dir():
        raise SystemExit('Save this installer in the existing invoice reader source folder.')
    files = json.loads(zlib.decompress(base64.b64decode(DATA)))
    pending = []
    for item in files:
        relative = Path(item['path'])
        if relative.is_absolute() or '..' in relative.parts or not (relative.parts[0] == 'Reading_V3' or str(relative) in ('Read_Invoice_V3.py', 'Teach_Invoice_Reader.py')):
            raise SystemExit('Unexpected update path; nothing changed.')
        text = item['text']
        if hashlib.sha256(text.encode()).hexdigest() != item['sha256']:
            raise SystemExit('Bundle verification failed; nothing changed.')
        if relative.suffix == '.py':
            ast.parse(text, filename=str(relative))
        path = package/relative
        if path.is_symlink() or any(parent.is_symlink() for parent in path.parents if parent != package.parent):
            raise SystemExit('Linked update path refused; nothing changed.')
        original = path.read_bytes() if path.exists() else None
        if original is not None:
            digest = hashlib.sha256(original).hexdigest()
            if digest == item['sha256']:
                continue
            if digest not in item.get('previous_sha256', []):
                raise SystemExit('Unrecognized local changes preserved; nothing changed: '+str(path))
        pending.append((relative, path, text.encode(), original))
    if not pending:
        print('Separate Reading V3.2 is already installed.')
        return
    backup = root/'.invoice_app/code_backups'/('reading_v3_2_'+datetime.now().strftime('%Y%m%d_%H%M%S_%f'))
    for relative, path, raw, original in pending:
        if original is not None:
            target = backup/relative
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(original)
    changed = []
    try:
        for relative, path, raw, original in pending:
            path.parent.mkdir(parents=True, exist_ok=True)
            changed.append((path, original))
            path.write_bytes(raw)
    except Exception:
        for path, original in reversed(changed):
            if original is None:
                path.unlink(missing_ok=True)
            else:
                path.write_bytes(original)
        raise
    print('Separate Reading V3.2 installed: supplier/layout teaching, source checks and review XML ready.')
    if backup.exists():
        print('Backup: '+str(backup))
    print('Active desktop, UQC catalog and Import ALL button unchanged.')
    print('Saved reviews/caches and financial values unchanged. No AI requests or Tally imports sent.')
    print('Teach an example: .venv\\Scripts\\python.exe Teach_Invoice_Reader.py \"path to example.pdf\"')
    print('Then run Read_Invoice_V3.py on new invoices with --xml --ai-provider Groq --max-ai-requests 50.')
    print('Reading_V3/TEACHING.md contains the instructions. Existing saved reads are not reread.')


if __name__ == '__main__':
    main()
